import sys, json, time, os, numpy as np

def cost(p, A, B):
    return int(np.sum(A * np.take(B, p, axis=0).T * np.take(B, p, axis=0)))

def local_search(p, A, B, start_time, time_limit, restart_limit=5):
    best_p = p.copy()
    best_cost = cost(p, A, B)
    restarts = 0
    n = len(p)
    while restarts < restart_limit and time.time() - start_time < time_limit:
        improved = False
        for i in range(n):
            for j in range(i+1, n):
                p[i], p[j] = p[j], p[i]
                new_cost = cost(p, A, B)
                if new_cost < best_cost:
                    best_cost = new_cost
                    best_p = p.copy()
                    improved = True
                p[i], p[j] = p[j], p[i]
                if time.time() - start_time >= time_limit:
                    return best_p, best_cost
        if not improved:
            break
        # schedule restarts proportionally to remaining time
        elapsed = time.time() - start_time
        remaining = time_limit - elapsed
        if remaining < 0.01:
            break
        # allocate roughly equal slices for the remaining restarts
        slice_len = max(0.01, remaining / (restart_limit - restarts))
        if elapsed + slice_len > time_limit:
            break
        time.sleep(slice_len)
        p = np.random.permutation(n).tolist()
        restarts += 1
    return best_p, best_cost

def main():
    if len(sys.argv) < 3:
        return
    json_path = sys.argv[1]
